import json
def transform(g):
    H,W=len(g),len(g[0]); seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==col and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                comps.append((col,cells))
    def norm(cells):
        rs=[r for r,c in cells]; cs=[c for r,c in cells]; m=min(rs),min(cs)
        return tuple(sorted((r-m[0],c-m[1]) for r,c in cells))
    cmap={}
    for col,c in comps:
        if col!=1: cmap.setdefault(norm(c),col)
    out=[row[:] for row in g]
    for col,cells in comps:
        if col==1 and norm(cells) in cmap:
            for r,c in cells: out[r][c]=cmap[norm(cells)]
    return out
